TLM.f("Tempora/Pent14-0",{"officium":"Dominica XIV Post Pentecosten","rule":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 83:10-11"},{"k":"text","la":"Protéctor noster, áspice, Deus, et réspice in fáciem Christi tui: quia mélior est dies una in átriis tuis super mília."},{"k":"ref","la":"Ps 83:2-3"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit, et déficit ánima mea in átria Dómini.","mark":"V"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protéctor noster, áspice, Deus, et réspice in fáciem Christi tui: quia mélior est dies una in átriis tuis super mília"}],"Oratio":[{"k":"text","la":"Custódi, Dómine, quǽsumus, Ecclésiam tuam propitiatióne perpétua: et quia sine te lábitur humána mortálitas; tuis semper auxíliis et abstrahátur a nóxiis et ad salutária dirigátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas."},{"k":"ref","la":"Gal 5:16-24"},{"k":"text","la":"Fratres: Spíritu ambuláte, et desidéria carnis non perficiétis. Caro enim concupíscit advérsus spíritum, spíritus autem advérsus carnem: hæc enim sibi ínvicem adversántur, ut non quæcúmque vultis, illa faciátis. Quod si spíritu ducímini, non estis sub lege. Manifésta sunt autem ópera carnis, quæ sunt fornicátio, immundítia, impudicítia, luxúria, idolórum sérvitus, venefícia, inimicítiæ, contentiónes, æmulatiónes, iræ, rixæ, dissensiónes, sectæ, invídiæ, homicídia, ebrietátes, comessatiónes, et his simília: quæ prædíco vobis, sicut prædíxi: quóniam, qui talia agunt, regnum Dei non consequántur. Fructus autem Spíritus est: cáritas, gáudium, pax, patiéntia, benígnitas, bónitas, longanímitas, mansuetúdo, fides, modéstia, continéntia, cástitas. Advérsus hujúsmodi non est lex. Qui autem sunt Christi, carnem suam crucifixérunt cum vítiis et concupiscéntiis."}],"Graduale":[{"k":"ref","la":"Ps 117:8-9"},{"k":"text","la":"Bonum est confidére in Dómino, quam confidére in hómine."},{"k":"text","la":"Bonum est speráre in Dómino, quam speráre in princípibus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 94:1"},{"k":"text","la":"Veníte, exsultémus Dómino, jubilémus Deo, salutári nostro. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 6:24-33"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nemo potest duóbus dóminis servíre: aut enim unum ódio habébit, et álterum díliget: aut unum sustinébit, et álterum contémnet. Non potéstis Deo servíre et mammónæ. Ideo dico vobis, ne sollíciti sitis ánimæ vestræ, quid manducétis, neque córpori vestro, quid induámini. Nonne ánima plus est quam esca: et corpus plus quam vestiméntum? Respícite volatília cœli, quóniam non serunt neque metunt neque cóngregant in hórrea: et Pater vester cœléstis pascit illa. Nonne vos magis pluris estis illis? Quis autem vestrum cógitans potest adjícere ad statúram suam cúbitum unum? Et de vestiménto quid sollíciti estis? Consideráte lília agri, quómodo crescunt: non labórant neque nent. Dico autem vobis, quóniam nec Sálomon in omni glória sua coopértus est sicut unum ex istis. Si autem fænum agri, quod hódie est et cras in clíbanum míttitur, Deus sic vestit: quanto magis vos módicæ fídei? Nolíte ergo sollíciti esse, dicéntes: Quid manducábimus aut quid bibémus aut quo operiémur? Hæc enim ómnia gentes inquírunt. Scit enim Pater vester, quia his ómnibus indigétis. Quǽrite ergo primum regnum Dei et justítiam ejus: et hæc ómnia adjiciéntur vobis."}],"Offertorium":[{"k":"ref","la":"Ps 33:8-9"},{"k":"text","la":"Immíttet Angelus Dómini in circúitu timéntium eum, et erípiet eos: gustáte et vidéte, quóniam suávis est Dóminus."}],"Secreta":[{"k":"text","la":"Concéde nobis, Dómine, quǽsumus, ut hæc hóstia salutáris et nostrórum fiat purgátio delictórum, et tuæ propitiátio potestátis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 6:33"},{"k":"text","la":"Primum quǽrite regnum Dei, et ómnia adjiciéntur vobis, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Puríficent semper et múniant tua sacraménta nos, Deus: et ad perpétuæ ducant salvatiónis efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9dc246d7ae5a8b19":{"t":"Ps 83, 10-11, Ps 83, 2-3\n(Ps 83, 10-11) Bože, štite naš, pogledaj i vidi lice pomazanika svojega. Zaista bolji je jedan dan u tvojim dvorovima nego tisuću drugih. (Ps 83, 2-3) Kako su mili stanovi tvoji, Gospodine vojska, duša moja čezne i gine od žudnje za dvorima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 83, 10-11) Bože, štite naš, pogledaj i vidi lice pomazanika svojega. Zaista bolji je jedan dan u tvojim dvorovima nego tisuću drugih."},"d9e47c4c34881f94":{"t":"<i>Pomolimo se</i>.\nČuvaj, molimo, Gospodine, svoju Crkvu neprestanom milošću i daj da se smrtni čovjek, nemoćan bez tebe, s tvojom pomoći vazda odvraća od onoga što je štetno, a usmjeri k onome što je spasonosno.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"42d75d27095fe989":{"t":"Gal 5, 16-24\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo, živite po Duhu, pa nećete udovoljavati požudama tijela, jer tijelo žudi protiv duha, a duh protiv tijela. Da, oni se protive jedan drugome, da ne činite ono što hoćete. Ako vas vodi Duh, niste pod zakonom. Poznata su djela tijela, a to su: bludnost, nečistoća, bestidnost, raspuštenost, idolopoklonstvo, vračanje, neprijateljstvo, svađe, prepirke, srdžba, spletke, razdor, sljedbe, zavist, ubojstva, pijanstvo, razuzdane gozbe i ovome slično. S obzirom na ova djela tijela unaprijed vam kažem, kao što sam već rekao: Oni koji čine takva djela neće biti baštinici Božjega kraljevstva. Ovo su pak plodovi duha: ljubav, radost, mir, strpljivost, blagost, dobrota, dugotrpnost, krotkost, vjernost, čednost, suzdržijivost, čistoća. Protiv takvih nema zakona. Oni koji su Kristovi raspeli su svoje tijelo s manama i požudama."},"071c5d3dda7d2037":{"t":"Ps 117, 8-9\nBolje se utjecati Gospodinu nego se pouzdavati u čovjeka. Bolje se utjecati Gospodinu nego se pouzdavati u knezove.\n\nPs 94, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nDođite, zapjevajmo Gospodinu, kličimo Bogu spasitelju našemu. <i>Aleluja</i>."},"7f3eafb4a57c0395":{"t":"Mt 6, 24-33\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Nitko ne može služiti dvama gospodarima, jer ili će jednoga mrziti, a drugoga ljubiti, ili će pristajati uz jednoga, a prezirati drugoga. Ne možete služiti Bogu i bogatstvu! Zato vam kažem: Ne brinite se toliko za svoj život što ćete jesti, ni za svoje tijelo što ćete obući. Zar život ne vrijedi više nego jelo, i tijelo više nego odijelo? Pogledajte ptice: niti siju, niti žanju, niti sabiru u žitnice, a hrani ih vaš nebeski Otac. Niste li vi daleko vrjedniji od njih? A tko od vas može svojom brigom dodati svojem rastu i jedan lakat? I za odijelo što vas toliko mori briga? Gledajte kako rastu ljiljani u polju: niti se trude, niti predu, a kažem vam da se ni Salamon u svojem punom sjaju nije odijevao kao jedan od njih. Pa ako Bog tako odijeva poljsku travu koja danas jest, a već se sutra baca u peć, koliko će više vas, malovjerni? Ne brinite se dakle toliko i ne govorite: što ćemo jesti ili u što ćemo se obući? Sve to traže nevjernici. Vaš nebeski Otac zna da vam sve to treba. Tražite prije svega Božje kraljevstvo i njegovu pravdu, a sve će vam se ostalo dati."},"ecab5ba75aa2b450":{"t":"Ps 33, 8-9\nAnđeo će Gospodnji saći među one, koji ga se boje, te će ih izbaviti. Kušajte i vidite kako je dobar Gospodin."},"dfb0bad4ea35358f":{"t":"Podaj, molimo, Gospodine, da nam ova spasonosna žrtva bude na očišćenje od grijeha, i da nam umilostivi tvoje veličanstvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"38a23cc53077df95":{"t":"Mt 6, 33\nTražite prije svega Božje kraljevstvo i njegovu pravdu, a sve će vam se ostalo dati, kaže Gospodin."},"dcdc88ea9182633e":{"t":"<i>Pomolimo se</i>.\nTvoja otajstva, Gospodine, neka nas uvijek čiste i utvrđuju i vode k vječnome spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
